const entry = $input.first().json.body.entry?.[0];
const change = entry?.changes?.[0]?.value;
const message = change?.messages?.[0];

if (!message) {
  return [{ json: { skip: true } }];
}

let text = '';
let buttonId = '';
let mediaId = '';
let mediaType = message.type || 'text';

if (message.type === 'text') {
  text = message.text?.body || '';
} else if (message.type === 'image') {
  mediaId = message.image?.id || '';
  text = message.image?.caption || '[User sent an image/flyer/photo. Please examine or acknowledge.]';
} else if (message.type === 'interactive') {
  if (message.interactive.type === 'button_reply') {
    buttonId = message.interactive.button_reply.id;
    text = message.interactive.button_reply.title;
  } else if (message.interactive.type === 'list_reply') {
    buttonId = message.interactive.list_reply.id;
    text = message.interactive.list_reply.title;
  }
}

return [{
  json: {
    skip: false,
    phone_number_id: change.metadata.phone_number_id,
    from_phone: message.from,
    wa_message_id: message.id,
    text: text,
    button_id: buttonId,
    media_id: mediaId,
    message_type: mediaType,
    profile_name: change.contacts?.[0]?.profile?.name || 'WhatsApp User'
  }
}];

const raw = $input.first().json;
const branch = Array.isArray(raw) ? raw[0] : raw;
if (!branch || !branch.branch_id) {
  throw new Error('No branch found for this WhatsApp phone_number_id. Add a row to whatsapp_sessions first.');
}
return [{ json: { branch_id: branch.branch_id } }];

const raw = $input.first().json;
const conv = Array.isArray(raw) ? raw[0] : raw;
return [{ json: { conversation_id: conv.id } }];

const item = $input.first().json;
return [{
  json: {
    reply: item.direct_reply,
    image_url: item.image_url || '',
    is_location: item.is_location || false,
    location_lat: item.location_lat || null,
    location_lng: item.location_lng || null,
    location_name: item.location_name || '',
    location_address: item.location_address || ''
  }
}];

let raw = '';
try {
  const data = $input.first().json;
  if (data.choices && data.choices[0]?.message?.content) {
    raw = data.choices[0].message.content.trim();
  } else if (data.candidates && data.candidates[0]?.content?.parts?.[0]?.text) {
    raw = data.candidates[0].content.parts[0].text.trim();
  } else if (typeof data === 'string') {
    raw = data;
  }
} catch (e) {
  raw = '';
}

// Extract [FLYER: <url>] or [IMAGE: <url>] if present
let flyerUrl = '';
const flyerMatch = raw.match(/\[FLYER:\s*([^\]]+)\]/i) || raw.match(/\[IMAGE:\s*([^\]]+)\]/i);
if (flyerMatch && flyerMatch[1]) {
  flyerUrl = flyerMatch[1].trim();
}

// Convert markdown headers ### Heading to *Heading*
let clean = raw.replace(/^#{1,6}\s*(.+)$/gm, '*$1*');

// Convert **bold** and ***bold*** to WhatsApp single *bold*
clean = clean.replace(/\*\*\*(.*?)\*\*\*/g, '*$1*');
clean = clean.replace(/\*\*(.*?)\*\*/g, '*$1*');
clean = clean.replace(/\*\*([^*]+)\*/g, '*$1*');
clean = clean.replace(/\*([^*]+)\*\*/g, '*$1*');

// Remove double underscores __italic__ to _italic_
clean = clean.replace(/__([^_]+)__/g, '_$1_');

// Remove any unwanted [FLYER:...] or [IMAGE:...] tags or raw storage URLs from text body
clean = clean.replace(/\[FLYER:\s*[^\]]+\]/gi, '');
clean = clean.replace(/\[IMAGE:\s*[^\]]+\]/gi, '');
clean = clean.replace(/https?:\/\/[^\s]+(?:supabase\.co|storage)[^\s]+\.(?:png|jpe?g|webp|gif)/gi, '');

// Clean multiple consecutive empty lines
clean = clean.replace(/\n{3,}/g, '\n\n').trim();

return [{ json: { reply: clean, image_url: flyerUrl } }];

let directReply = '';
try { directReply = $('Format Direct Reply').first().json.reply || ''; } catch (e) {}

let aiReply = '';
try { aiReply = $('Extract AI Reply').first().json.reply || ''; } catch (e) {}

let phoneNumberId = '';
let fromPhone = '';
try {
  phoneNumberId = $('Parse Incoming Message').first().json.phone_number_id || '';
  fromPhone = $('Parse Incoming Message').first().json.from_phone || '';
} catch (e) {}

const inputData = $json || {};
const textReply = inputData.reply || inputData.message || directReply || aiReply || "Thank you for reaching out to RCCG Everflourishing Mega Sanctuary!";

return [{ json: { fallback_text: textReply, phone_number_id: phoneNumberId, from_phone: fromPhone } }];

let directData = {};
try { directData = $('Format Direct Reply').first().json || {}; } catch (e) {}

let aiData = {};
try { aiData = $('Extract AI Reply').first().json || {}; } catch (e) {}

const inputData = $json || {};
let textReply = inputData.reply || inputData.message || directData.reply || aiData.reply || '';
let flyerUrl = inputData.image_url || directData.image_url || '';
const isLocation = inputData.is_location || directData.is_location || false;

// WhatsApp image caption limit is 1024 characters max
if (textReply.length > 1000) {
  textReply = textReply.substring(0, 995) + '...';
}

// Sanitize flyerUrl: WhatsApp rejects base64 data: URLs and non-http strings
const storageBase = 'https://xzyrftzhaolovlbnpbpk.supabase.co/storage/v1/object/public/Flyers';
if (flyerUrl && (flyerUrl.startsWith('data:image') || (!flyerUrl.startsWith('http://') && !flyerUrl.startsWith('https://')))) {
  flyerUrl = storageBase + '/Service/First%20Service.jpg';
}

let phoneNumberId = '';
let fromPhone = '';
try {
  phoneNumberId = $('Parse Incoming Message').first().json.phone_number_id || '';
  fromPhone = $('Parse Incoming Message').first().json.from_phone || '';
} catch (e) {}

return [{ json: {
  reply: textReply,
  image_url: flyerUrl,
  phone_number_id: phoneNumberId,
  from_phone: fromPhone,
  is_location: isLocation,
  location_lat: inputData.location_lat || directData.location_lat || null,
  location_lng: inputData.location_lng || directData.location_lng || null,
  location_name: inputData.location_name || directData.location_name || '',
  location_address: inputData.location_address || directData.location_address || ''
} }];

let errMsg = '';
try { errMsg = JSON.stringify($json.error || $json); } catch (e) { errMsg = String($json); }

const isRateLimit = /429|rate.?limit|quota/i.test(errMsg);

const reply = isRateLimit
  ? "We're getting a lot of messages right now 🙏 Please give us a moment and try again shortly, or a team member will respond soon."
  : "We've received your message! Someone from our team will get back to you shortly. 🙏";

return [{ json: { reply, image_url: '' } }];

const now = new Date();
const storageBase = 'https://xzyrftzhaolovlbnpbpk.supabase.co/storage/v1/object/public/Flyers';

function fmtWAT(d) {
  return d.toLocaleString('en-US', { timeZone: 'Africa/Lagos', weekday: 'long', month: 'long', day: 'numeric' });
}
function isoDateWAT(d) {
  return d.toLocaleString('en-CA', { timeZone: 'Africa/Lagos', year: 'numeric', month: '2-digit', day: '2-digit' });
}
function atWATTime(base, hour, minute) {
  const dateStr = isoDateWAT(base);
  return new Date(`${dateStr}T${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}:00+01:00`);
}
function daysBetween(isoA, isoB) {
  const a = new Date(isoA + 'T00:00:00+01:00');
  const b = new Date(isoB + 'T00:00:00+01:00');
  return Math.round((b - a) / 86400000);
}
function nextWeeklyOccurrence(targetDow, hour, minute) {
  let d = new Date(now);
  for (let i = 0; i < 8; i++) {
    const candidate = atWATTime(d, hour, minute);
    if (candidate.getDay() === targetDow && candidate.getTime() > now.getTime()) return candidate;
    d.setDate(d.getDate() + 1);
  }
  return atWATTime(now, hour, minute);
}
function nextLastWeekdayOfMonthOccurrence(targetDow, hour, minute) {
  function lastWeekdayOf(year, month) {
    const lastDay = new Date(year, month + 1, 0);
    const diff = (lastDay.getDay() - targetDow + 7) % 7;
    lastDay.setDate(lastDay.getDate() - diff);
    return lastDay;
  }
  const nowLagos = new Date(now.toLocaleString('en-US', { timeZone: 'Africa/Lagos' }));
  let candidate = atWATTime(lastWeekdayOf(nowLagos.getFullYear(), nowLagos.getMonth()), hour, minute);
  if (candidate.getTime() <= now.getTime()) {
    const nextMonth = new Date(nowLagos.getFullYear(), nowLagos.getMonth() + 1, 1);
    candidate = atWATTime(lastWeekdayOf(nextMonth.getFullYear(), nextMonth.getMonth()), hour, minute);
  }
  return candidate;
}
function currentOrNextSundayDate() {
  const nowLagos = new Date(now.toLocaleString('en-US', { timeZone: 'Africa/Lagos' }));
  const daysUntilSun = (7 - nowLagos.getDay()) % 7;
  const d = new Date(nowLagos);
  d.setDate(d.getDate() + daysUntilSun);
  return d;
}
function sundayOccurrenceAt(hour, minute) {
  return atWATTime(currentOrNextSundayDate(), hour, minute);
}

const todayISO = isoDateWAT(now);
const due = [];

function safeAll(nodeName) {
  try {
    return $(nodeName).all()
      .map(function (i) { return i.json; })
      .filter(function (j) { return j && (j.title || j.event_date || j.program_date); });
  } catch (e) { return []; }
}
const dbEvents = safeAll('Fetch Reminder Events');
const dbPrograms = safeAll('Fetch Reminder Programs');

function findEventOverride(isoDate) {
  return dbEvents.find(function (e) {
    return (e.event_date || '').slice(0, 10) === isoDate;
  });
}
function programCovers(isoDate) {
  return dbPrograms.some(function (p) {
    const s = (p.program_date || '').slice(0, 10);
    const en = (p.end_date || p.program_date || '').slice(0, 10);
    return s && isoDate >= s && isoDate <= en;
  });
}
function startParts(item, defH, defM) {
  const t = ((item && item.start_time) || '').split('-')[0].trim();
  if (!t.includes(':')) return [defH, defM];
  const p = t.split(':');
  return [parseInt(p[0], 10) || defH, parseInt(p[1], 10) || 0];
}
function pickFlyer(item, fallback) {
  const u = item.image_url || item.flyer_url || item.banner_url || '';
  if (typeof u === 'string' && u.trim().startsWith('https://')) return u.trim();
  const desc = String(item.description || '');
  const m = desc.match(/\[FLYER:\s*([^\]]+)\]/i);
  if (m && m[1].trim().startsWith('https://')) return m[1].trim();
  return fallback;
}
function cleanDescription(desc) {
  return String(desc || '')
    .replace(/\[FLYER:[^\]]*\]/gi, '')
    .replace(/\[SCRIPTURE:[^\]]*\]/gi, '')
    .replace(/\s+/g, ' ')
    .trim();
}
function looksLikeReference(s) {
  return /^\d?\s?[A-Za-z]+(?:\s[A-Za-z]+)*\s+\d{1,3}:\d{1,3}(?:-\d{1,3})?$/.test(String(s || '').trim());
}
function toBibleApiSlug(ref) {
  return String(ref).trim().replace(/\s+/g, '+');
}

const verseCache = {};
const fetchVerseText = async (ref) => {
  if (verseCache[ref] !== undefined) return verseCache[ref];
  let result = null;
  try {
    const url = 'https://bible-api.com/' + toBibleApiSlug(ref) + '?translation=kjv';
    const res = await this.helpers.httpRequest({ method: 'GET', url, json: true, timeout: 8000 });
    if (res && res.text) {
      result = '"' + String(res.text).trim().replace(/\s+/g, ' ') + '" — ' + (res.reference || ref);
    }
  } catch (e) { result = null; }
  verseCache[ref] = result;
  return result;
};

async function resolveVerse(item, fallback) {
  if (!item) return fallback;
  let rawRef = String(item.scripture || item.verse || '').trim();
  if (!rawRef && item.description) {
    const m = String(item.description).match(/\[SCRIPTURE:\s*([^\]]+)\]/i);
    if (m && m[1].trim()) rawRef = m[1].trim();
  }
  if (!rawRef) return fallback;
  if (looksLikeReference(rawRef)) {
    const fetched = await fetchVerseText(rawRef);
    return fetched || fallback;
  }
  return (rawRef.startsWith('"') || rawRef.startsWith('\u201C')) ? rawRef : ('"' + rawRef + '"');
}

const hasOverrideToday = programCovers(todayISO);

const weekdayServices = [
  { name: 'Digging Deep (Bible Study)', occurrence: nextWeeklyOccurrence(2, 18, 0), flyer: storageBase + '/Service/Digging%20Deep.png', verse: '"Study to shew thyself approved unto God." — 2 Tim 2:15', description: '' },
  { name: 'Faith Clinic (Miracle Hour)', occurrence: nextWeeklyOccurrence(4, 18, 0), flyer: storageBase + '/Service/faith%20clinic.jpg', verse: '"The prayer of faith shall save the sick." — James 5:15', description: '' },
  { name: 'Youth Vigil (YAYA)', occurrence: nextLastWeekdayOfMonthOccurrence(3, 23, 0), flyer: storageBase + '/Service/Youth%20vigil.jpg', verse: '"Continue in prayer, and watch in the same with thanksgiving." — Col 4:2', description: '' }
];

for (const svc of weekdayServices) {
  const svcDateISO = isoDateWAT(svc.occurrence);
  const svcOverride = findEventOverride(svcDateISO);
  if (svcOverride) {
    if (String(svcOverride.start_time || '').includes(':')) {
      const sp = startParts(svcOverride, 18, 0);
      svc.occurrence = atWATTime(new Date(svcDateISO + 'T00:00:00+01:00'), sp[0], sp[1]);
    }
    svc.name = svcOverride.title || svc.name;
    svc.flyer = pickFlyer(svcOverride, svc.flyer);
    svc.verse = await resolveVerse(svcOverride, svc.verse);
    svc.description = cleanDescription(svcOverride.description);
  }
  const daysAway = daysBetween(todayISO, svcDateISO);
  const timeLabel = svc.occurrence.toLocaleString('en-US', { timeZone: 'Africa/Lagos', hour: 'numeric', minute: '2-digit' });
  const dateLabel = fmtWAT(svc.occurrence);
  if (daysAway === 0 && !hasOverrideToday) {
    for (const off of [{ type: '1h', minutes: 60, label: 'IN 1 HOUR' }, { type: '30m', minutes: 30, label: 'IN 30 MINUTES' }]) {
      const sendAt = new Date(svc.occurrence.getTime() - off.minutes * 60000);
      if (sendAt.getTime() <= now.getTime()) continue;
      due.push({ json: { should_send: true, service_name: svc.name, reminder_type: off.type, dedup_key: `${svc.name} :: ${off.type}`, occurrence_date: svcDateISO, flyer_url: svc.flyer, send_at: sendAt.toISOString(), tpl_service_upper: svc.name.toUpperCase(), tpl_offset_upper: off.label, tpl_service_name: svc.name, tpl_date_label: dateLabel, tpl_time_label: timeLabel, tpl_verse: svc.verse, tpl_description: svc.description || '' } });
    }
  }
}

const sundayBase = currentOrNextSundayDate();
const sunDayOfMonth = sundayBase.getDate();
let sundayService = null;
const sundayWeekOfMonth = Math.ceil(sunDayOfMonth / 7);
if (sundayWeekOfMonth === 1) {
  sundayService = { name: 'Thanksgiving Sunday Service', occurrence: sundayOccurrenceAt(8, 0), flyer: storageBase + '/Service/Thanks.jpg', verse: '"Enter into his gates with thanksgiving." — Psalm 100:4', description: '' };
} else if (sundayWeekOfMonth === 2) {
  sundayService = { name: 'Prayer Sunday', occurrence: sundayOccurrenceAt(8, 0), flyer: storageBase + '/Service/Second%20Servivce.jpg', verse: '"Call unto me, and I will answer thee." — Jeremiah 33:3', description: '' };
} else if (sundayWeekOfMonth === 3) {
  sundayService = { name: 'Youth Sunday', occurrence: sundayOccurrenceAt(8, 0), flyer: storageBase + '/Service/First%20Service.jpg', verse: '"Let no man despise thy youth." — 1 Timothy 4:12', description: '' };
} else if (sundayWeekOfMonth === 4) {
  sundayService = { name: 'Super Sunday / Relationship Sunday', occurrence: sundayOccurrenceAt(8, 0), flyer: storageBase + '/Service/First%20Service.jpg', verse: '"Put on charity, which is the bond of perfectness." — Colossians 3:14', description: '' };
} else {
  sundayService = { name: '5th Sunday — CSR / Welfare Sunday', occurrence: sundayOccurrenceAt(8, 0), flyer: storageBase + '/Service/First%20Service.jpg', verse: '"As we have therefore opportunity, let us do good unto all men." — Galatians 6:10', description: '' };
}

const sunISO = isoDateWAT(sundayService.occurrence);
const sunOverride = findEventOverride(sunISO);
if (sunOverride) {
  const sunStart = startParts(sunOverride, 8, 0);
  const resolvedVerse = await resolveVerse(sunOverride, sundayService.verse);
  sundayService = {
    name: sunOverride.title || sundayService.name,
    occurrence: atWATTime(new Date(sunISO + 'T00:00:00+01:00'), sunStart[0], sunStart[1]),
    flyer: pickFlyer(sunOverride, sundayService.flyer),
    verse: resolvedVerse,
    description: cleanDescription(sunOverride.description)
  };
}

if (sundayService) {
  const sunDateISO = isoDateWAT(sundayService.occurrence);
  const sunDaysAway = daysBetween(todayISO, sunDateISO);
  const sunTimeLabel = sundayService.occurrence.toLocaleString('en-US', { timeZone: 'Africa/Lagos', hour: 'numeric', minute: '2-digit' });
  const sunDateLabel = fmtWAT(sundayService.occurrence);

  if (sunDaysAway === 1) {
    const sendAt = atWATTime(new Date(todayISO + 'T00:00:00+01:00'), 19, 0);
    if (sendAt.getTime() > now.getTime()) {
      due.push({ json: { should_send: true, service_name: sundayService.name, reminder_type: '1d', dedup_key: `${sundayService.name} :: 1d`, occurrence_date: sunDateISO, flyer_url: sundayService.flyer, send_at: sendAt.toISOString(), tpl_service_upper: sundayService.name.toUpperCase(), tpl_offset_upper: 'TOMORROW', tpl_service_name: sundayService.name, tpl_date_label: sunDateLabel, tpl_time_label: sunTimeLabel, tpl_verse: sundayService.verse, tpl_description: sundayService.description || '' } });
    }
  }
  if (sunDaysAway === 0 && !hasOverrideToday) {
    for (const off of [{ type: '1h', minutes: 60, label: 'IN 1 HOUR' }, { type: '30m', minutes: 30, label: 'IN 30 MINUTES' }]) {
      const sendAt = new Date(sundayService.occurrence.getTime() - off.minutes * 60000);
      if (sendAt.getTime() <= now.getTime()) continue;
      due.push({ json: { should_send: true, service_name: sundayService.name, reminder_type: off.type, dedup_key: `${sundayService.name} :: ${off.type}`, occurrence_date: sunDateISO, flyer_url: sundayService.flyer, send_at: sendAt.toISOString(), tpl_service_upper: sundayService.name.toUpperCase(), tpl_offset_upper: off.label, tpl_service_name: sundayService.name, tpl_date_label: sunDateLabel, tpl_time_label: sunTimeLabel, tpl_verse: sundayService.verse, tpl_description: sundayService.description || '' } });
    }
  }
}

try {
  for (const sp of dbPrograms) {
    if (!sp || !sp.program_date) continue;
    const programStart = sp.program_date.substring(0, 10);
    const programEnd = sp.end_date ? sp.end_date.substring(0, 10) : programStart;

    let startHour = 18, startMinute = 0;
    const timeStr = (sp.start_time || '').split('-')[0].trim();
    if (timeStr.includes(':')) {
      const parts = timeStr.split(':');
      startHour = parseInt(parts[0], 10) || 18;
      startMinute = parseInt(parts[1], 10) || 0;
    }

    const eventOccurrence = atWATTime(new Date(programStart + 'T00:00:00+01:00'), startHour, startMinute);
    const flyerUrl = pickFlyer(sp, storageBase + '/Service/First%20Service.jpg');
    const verse = await resolveVerse(sp, '"For I know the plans I have for you." — Jeremiah 29:11');
    const description = cleanDescription(sp.description);
    const timeLabel = eventOccurrence.toLocaleString('en-US', { timeZone: 'Africa/Lagos', hour: 'numeric', minute: '2-digit' });
    const dateLabel = fmtWAT(eventOccurrence);
    const spName = sp.title || 'Special Program';
    const daysToStart = daysBetween(todayISO, programStart);

    for (const adv of [{ days: 5, type: '5d', label: 'IN 5 DAYS' }, { days: 3, type: '3d', label: 'IN 3 DAYS' }, { days: 1, type: '1d', label: 'TOMORROW' }]) {
      if (daysToStart === adv.days) {
        const sendAt = atWATTime(new Date(todayISO + 'T00:00:00+01:00'), 8, 0);
        if (sendAt.getTime() > now.getTime()) {
          due.push({ json: { should_send: true, service_name: spName, reminder_type: adv.type, dedup_key: `${spName} :: ${adv.type}`, occurrence_date: programStart, flyer_url: flyerUrl, send_at: sendAt.toISOString(), tpl_service_upper: spName.toUpperCase(), tpl_offset_upper: adv.label, tpl_service_name: spName, tpl_date_label: dateLabel, tpl_time_label: timeLabel, tpl_verse: verse, tpl_description: description }  });
        }
      }
    }

    if (todayISO >= programStart && todayISO <= programEnd) {
      const todayOccurrence = atWATTime(new Date(todayISO + 'T00:00:00+01:00'), startHour, startMinute);
      const todayTimeLabel = todayOccurrence.toLocaleString('en-US', { timeZone: 'Africa/Lagos', hour: 'numeric', minute: '2-digit' });
      const todayDateLabel = fmtWAT(todayOccurrence);
      for (const off of [{ type: '1h', minutes: 60, label: 'IN 1 HOUR' }, { type: '30m', minutes: 30, label: 'IN 30 MINUTES' }]) {
        const sendAt = new Date(todayOccurrence.getTime() - off.minutes * 60000);
        if (sendAt.getTime() <= now.getTime()) continue;
        due.push({ json: { should_send: true, service_name: spName, reminder_type: off.type, dedup_key: `${spName} :: today :: ${off.type}`, occurrence_date: todayISO, flyer_url: flyerUrl, send_at: sendAt.toISOString(), tpl_service_upper: spName.toUpperCase(), tpl_offset_upper: off.label, tpl_service_name: spName, tpl_date_label: todayDateLabel, tpl_time_label: todayTimeLabel, tpl_verse: verse, tpl_description: description } });
      }
    }
  }
} catch (e) {}

due.sort((a, b) => new Date(a.json.send_at) - new Date(b.json.send_at));
return due;

const allMembers = $('Fetch All WhatsApp Members').all();

// Include all members except explicitly inactive ones
const members = allMembers.filter(function(m) {
  const st = (m.json.membership_status || '').toLowerCase().trim();
  return st !== 'inactive';
});

const phoneNumberIdData = $input.first().json;
let phoneNumberId = Array.isArray(phoneNumberIdData)
  ? phoneNumberIdData[0]?.phone_number_id
  : (phoneNumberIdData?.phone_number_id || '');

if (!phoneNumberId) {
  phoneNumberId = '1252855381239526';
}

const defaultFlyer = 'https://xzyrftzhaolovlbnpbpk.supabase.co/storage/v1/object/public/Flyers/Service/First%20Service.jpg';

// Get the active due reminder from the loop batch
let due = {};
try {
  due = $('Determine Due Reminders').first().json || {};
} catch (e) {}

try {
  const currentBatch = $('Loop Reminders').first().json;
  if (currentBatch && currentBatch.service_name) {
    due = currentBatch;
  }
} catch (e) {}

const flyerUrl = (due.flyer_url && due.flyer_url.startsWith('https://')) ? due.flyer_url : defaultFlyer;
let verse = due.tpl_verse || '"The prayer of faith shall save the sick." — James 5:15';
if (verse.length > 300) verse = verse.substring(0, 297) + '...';

const results = [];
for (let i = 0; i < members.length; i++) {
  const memberData = members[i].json;
  let memberPhone = (memberData.phone || '').replace(/[^0-9]/g, '');
  if (memberPhone.startsWith('0') && memberPhone.length === 11) {
    memberPhone = '234' + memberPhone.slice(1);
  } else if (memberPhone.length === 10 && !memberPhone.startsWith('234')) {
    memberPhone = '234' + memberPhone;
  }
  if (!memberPhone || memberPhone.length < 10) continue;

