function isValidHttpUrl(u) {
  if (!u || typeof u !== 'string') return false;
  const trimmed = u.trim();
  if (trimmed.startsWith('data:image')) return false;
  return trimmed.startsWith('https://') || trimmed.startsWith('http://');
}

function cleanDescription(desc) {
  if (!desc) return '';
  return desc
    .replace(/\[FLYER:\s*[^\]]+\]/gi, '')
    .replace(/\[IMAGE:\s*[^\]]+\]/gi, '')
    .replace(/\[SCRIPTURE:\s*[^\]]+\]/gi, '')
    .replace(/https?:\/\/[^\s]+(?:supabase\.co|storage)[^\s]+\.(?:png|jpe?g|webp|gif)/gi, '')
    .replace(/Flyer:\s*https?:\/\/[^\s]+/gi, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function formatTime(t) {
  if (!t) return '';
  const parts = t.trim().split(':');
  let h = parseInt(parts[0], 10);
  if (isNaN(h)) return t;
  const m = parts[1] ? parts[1].padStart(2, '0') : '00';
  const ampm = h >= 12 ? 'PM' : 'AM';
  h = h % 12 || 12;
  return h + ':' + m + ' ' + ampm;
}

function formatTimeRange(start, end) {
  if (!start) return '';
  const s = formatTime(start);
  const e = end ? formatTime(end) : '';
  return e ? (s + ' – ' + e) : s;
}

function formatDatePretty(isoStr) {
  if (!isoStr) return '';
  try {
    const d = new Date(isoStr.slice(0, 10) + 'T00:00:00+01:00');
    return d.toLocaleDateString('en-US', {
      weekday: 'long',
      month: 'short',
      day: 'numeric',
      year: 'numeric'
    });
  } catch (e) {
    return isoStr;
  }
}

function resolveFlyer(item) {
  if (!item) return storageBase + '/Service/First%20Service.jpg';

  if (isValidHttpUrl(item.image_url)) return item.image_url.trim();
  if (isValidHttpUrl(item.flyer_url)) return item.flyer_url.trim();
  if (isValidHttpUrl(item.banner_url)) return item.banner_url.trim();

  if (item.description) {
    const m = item.description.match(/\[FLYER:\s*([^\s\]]+)\]/i);
    if (m && isValidHttpUrl(m[1])) return m[1].trim();
    const m2 = item.description.match(/(https?:\/\/[^\s\]\)\<\>]+\.(?:png|jpe?g|webp|gif))/i);
    if (m2 && isValidHttpUrl(m2[1])) return m2[1].trim();
  }

  const t = (item.title || '').toLowerCase();
  for (const f of KNOWN_FLYERS) {
    if (t.includes(f.match)) return f.url;
  }

  return storageBase + '/Service/First%20Service.jpg';
}

function resolveScripture(item, defaultScripture) {
  if (!item) return defaultScripture || '';
  if (item.scripture && typeof item.scripture === 'string' && item.scripture.trim()) {
    let s = item.scripture.trim();
    if (!s.startsWith('"') && !s.startsWith('"')) s = '"' + s + '"';
    return s;
  }
  if (item.verse && typeof item.verse === 'string' && item.verse.trim()) {
    let s = item.verse.trim();
    if (!s.startsWith('"') && !s.startsWith('"')) s = '"' + s + '"';
    return s;
  }
  if (item.description) {
    const m = item.description.match(/\[SCRIPTURE:\s*([^\]]+)\]/i);
    if (m && m[1]) return '"' + m[1].trim() + '"';
  }
  const t = (item.title || '').toLowerCase();
  if (t.includes('nakedness') || t.includes('divine encounter') || t.includes('encounter')) {
    return '"And the Lord shall guide thee continually, and satisfy thy soul in drought, and make fat thy bones." — Isaiah 58:11';
