function sundayTypeFor(dayOfMonth) {
  const wk = Math.ceil(dayOfMonth / 7);
  if (wk === 1) return 'Thanksgiving Sunday';
  if (wk === 2) return 'Prayer Sunday';
  if (wk === 3) return 'Youth Sunday';
  if (wk === 4) return 'Super Sunday / Relationship Sunday';
  return '5th Sunday — CSR / Welfare Sunday';
}
