const now = new Date();

function isoDateWAT(d) {
  return d.toLocaleString('en-CA', { timeZone: 'Africa/Lagos', year: 'numeric', month: '2-digit', day: '2-digit' });
}

const dayName = now.toLocaleString('en-US', { timeZone: 'Africa/Lagos', weekday: 'long' }).toLowerCase();
const todayISO = isoDateWAT(now);

const items = $input.all();
const due = [];

for (const item of items) {
  const b = item.json || {};

  let days = b.days_of_week || b.repeat_days || b.days || [];
  if (typeof days === 'string') {
    days = days.replace(/[{}]/g, '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
  } else if (Array.isArray(days)) {
    days = days.map(s => String(s).toLowerCase().trim());
  }

  if (!days.includes(dayName)) continue;

  const sendTime = b.send_time || b.time || '17:00:00';
  const [hh, mm] = String(sendTime).split(':').map(Number);
  const sendAt = new Date(`${todayISO}T${String(hh || 0).padStart(2,'0')}:${String(mm || 0).padStart(2,'0')}:00+01:00`);

  // Skip if today's slot already passed (will pick it up again on its next scheduled day)
  if (sendAt.getTime() <= now.getTime()) continue;

  due.push({
    json: {
      broadcast_id: b.id,
      title: b.title || b.campaign_title || 'Announcement',
      message_body: b.message_body || b.message || b.body || '',
      flyer_url: b.flyer_url || b.image_url || '',
      target_audience: b.target_audience || 'all',
      occurrence_date: todayISO,
      send_at: sendAt.toISOString()
    }
  });
}

return due;
